.vf{
  --anatomy-paper:var(--cream-50);--anatomy-face:#FFFFFF;--anatomy-top:#FFFFFF;
  --anatomy-shade-0:#D6D4CD;--anatomy-shade-1:#E0DED8;--anatomy-shade-2:#EAE9E4;--anatomy-shade-3:#F4F3EF;
  --anatomy-lit-top:#FFFFFF;--anatomy-lit-shade:#EAF4FA;
  --anatomy-hi:#262A31;--anatomy-mid:#77766F;--anatomy-lo:#A9A7A0;--anatomy-faint:#D2D0C9;--anatomy-lit:var(--sky);
  --anatomy-halo:#8A8678;--anatomy-halo-opacity:.3;--anatomy-dot:#3A3D44;
}
html.dark .vf{
  --anatomy-face:#1B1E24;--anatomy-top:#1D2026;
  --anatomy-shade-0:#101216;--anatomy-shade-1:#13161A;--anatomy-shade-2:#16191E;--anatomy-shade-3:#1A1D22;
  --anatomy-lit-top:#1F2730;--anatomy-lit-shade:#17202A;
  --anatomy-hi:#D9DADD;--anatomy-mid:#6C7079;--anatomy-lo:#42464E;--anatomy-faint:#2B2F36;
  --anatomy-halo:#000000;--anatomy-halo-opacity:.85;--anatomy-dot:#E6E6E6;
}
.vf-stage{position:relative;padding:4px 8px 0;-webkit-tap-highlight-color:transparent;outline:none;touch-action:pan-y}
.vf-stage:focus-visible{outline:1px solid var(--ink-muted);outline-offset:-4px;border-radius:6px}
.vf .iso-svg{display:block;width:100%;height:auto;overflow:visible}
.vf .iso-svg path,.vf .iso-svg circle{vector-effect:non-scaling-stroke}
.vf .iso-fill{fill:var(--anatomy-paper);stroke:none}
.vf .iso-solid[data-lit]>.iso-fill{fill:var(--anatomy-face)}
.vf .iso-shade,.vf .iso-top{stroke:none}
.vf .iso-shade[data-shade="0"]{fill:var(--anatomy-shade-0)}
.vf .iso-shade[data-shade="1"]{fill:var(--anatomy-shade-1)}
.vf .iso-shade[data-shade="2"]{fill:var(--anatomy-shade-2)}
.vf .iso-shade[data-shade="3"]{fill:var(--anatomy-shade-3)}
.vf .iso-top{fill:var(--anatomy-top)}
.vf .iso-halo{fill:var(--anatomy-halo);stroke:none;filter:blur(9px);opacity:var(--anatomy-halo-opacity);transform:translateY(3px)}
.vf .iso-halo.vf-soft{filter:blur(4px);transform:translateY(1px)}
.vf .iso-line{fill:none;stroke:var(--anatomy-lo);stroke-width:.7px;stroke-linecap:round;stroke-linejoin:round}
.vf .iso-line[data-tone="hi"]{stroke:var(--anatomy-hi)}
.vf .iso-line[data-tone="mid"]{stroke:var(--anatomy-mid)}
.vf .iso-line[data-tone="lo"]{stroke:var(--anatomy-lo)}
.vf .iso-line[data-tone="faint"]{stroke:var(--anatomy-faint)}
.vf .iso-line[data-tone="lit"]{stroke:var(--anatomy-lit)}
.vf .iso-dots circle{fill:var(--anatomy-dot);stroke:none;opacity:.32}
.vf .iso-dots[data-tone="hi"] circle{opacity:.85}
.vf .iso-dots[data-tone="mid"] circle{opacity:.45}
.vf .iso-dots[data-tone="lo"] circle{opacity:.22}
.vf-engraved{fill:var(--anatomy-mid);font-family:Inter,system-ui,sans-serif;font-weight:600;letter-spacing:.02em}
.vf-grid{fill:none;stroke:#FFFFFF;stroke-opacity:.35;stroke-width:.5px}
.vf-edge-fill{fill:var(--sky);fill-opacity:.16}
.vf-stairs{fill:none;stroke:var(--sky);stroke-width:1.3px;stroke-linecap:square}
.vf-stairs-soft{stroke-opacity:.45;stroke-width:.8px}
.vf-outline{fill:none;stroke:var(--sky);stroke-width:1px;stroke-linejoin:round}
.vf-anchor{fill:#FFFFFF;stroke:var(--sky);stroke-width:.9px}
.vf-handle{fill:none;stroke:var(--sky);stroke-width:.7px;stroke-opacity:.85}
.vf-handle-dot{fill:var(--sky);stroke:none}
.vf .iso-svg *{pointer-events:none}
.vf .iso-svg .vf-hit{pointer-events:all}
.vf .iso-svg .vf-station,.vf .iso-svg .vf-station *{pointer-events:visiblePainted;cursor:pointer}
.vf-station:hover .vf-head>.iso-edge{stroke:var(--anatomy-lit)}
.vf-hit{fill:none;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
.vf-target{fill:var(--sky);fill-opacity:.22;stroke:var(--sky);stroke-width:1px}
.vf-scan{fill:none;stroke:var(--sky);stroke-width:1.4px}
.vf-scan-glow{fill:none;stroke:var(--sky);stroke-width:7px;stroke-opacity:.45}
.vf-tip{fill:var(--sky)}
.vf-tip-glow{fill:var(--sky);opacity:.5}
.vf-ink{stroke:none}
.vf-cap>.iso-top{fill:var(--vf-ink)}
.vf-coil{stroke-width:.8px}
.vf-lamp>.iso-top,.vf-lamp>.iso-shade{fill:var(--anatomy-shade-1)}
.vf-lamp-line{opacity:.35;transition:opacity .4s ease}
.vf-station[data-active] .vf-lamp-line{opacity:1}
.vf-station .vf-head>.iso-edge{transition:stroke .4s ease}
.vf-station[data-active] .vf-head>.iso-edge{stroke:var(--anatomy-lit)}
.vf-station[data-active] .vf-head>.iso-top{fill:var(--anatomy-lit-top)}
.vf-station[data-active] .vf-head>.iso-shade{fill:var(--anatomy-lit-shade)}
.vf-chip{display:flex;flex-direction:column;align-items:flex-start;gap:6px;width:100%;height:100%;padding:16px 20px;text-align:left;color:rgb(var(--ink-muted-rgb));transition:color .3s ease,background-color .3s ease}
.vf-chip-head{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:500;color:rgb(var(--ink-rgb))}
.vf-chip-note{font-size:13px;line-height:1.5}
.vf-chip[data-on]{background:rgb(var(--sky-rgb) / .05)}
.vf-chip:hover{color:rgb(var(--ink-rgb))}
.vf-chip-num{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:999px;border:1px solid rgb(var(--cream-300-rgb));font-size:10px;line-height:1;font-variant-numeric:tabular-nums;color:rgb(var(--ink-muted-rgb))}
.vf-chip[data-on] .vf-chip-title{color:rgb(var(--sky-rgb))}
.vf-chip[data-on] .vf-chip-num{border-color:rgb(var(--sky-rgb));background:rgb(var(--sky-rgb));color:#FFFFFF}
.vf-chip[data-done] .vf-chip-num{border-color:rgb(var(--sky-rgb) / .5);color:rgb(var(--sky-rgb))}
@media (prefers-reduced-motion:reduce){.vf *{transition:none!important}}
@media (max-width:640px){.vf-stage{overflow:hidden;padding:0}.vf-stage .iso-svg{width:190%;max-width:none;margin:-3% 0 -2%}}
